export function getToolBySlug(slug: string): ToolInfo | undefined {
  return tools.find(t => t.slug === slug);
}

export function getToolsByCategory(category: string): ToolInfo[] {
  return tools.filter(t => t.category === category);
}

export function getPopularTools(limit = 12): ToolInfo[] {
  return tools.filter(t => t.isPopular && t.isActive).slice(0, limit);
}

export function searchTools(query: string, categoryFilter?: string): ToolInfo[] {
  const q = query.toLowerCase().trim();
  return tools.filter(t => {
    if (!t.isActive) return false;
    if (categoryFilter && categoryFilter !== 'all' && t.category !== categoryFilter) return false;
    if (!q) return true;
    return (
      t.name.toLowerCase().includes(q) ||
      t.description.toLowerCase().includes(q) ||
      t.categoryLabel.toLowerCase().includes(q) ||
      t.keywords.some(k => k.toLowerCase().includes(q))
    );
  });
}

export function getRelatedTools(currentSlug: string, limit = 4): ToolInfo[] {
  const current = getToolBySlug(currentSlug);
  if (!current) return tools.filter(t => t.isActive).slice(0, limit);
  
  const sameCategory = tools.filter(t => t.category === current.category && t.slug !== currentSlug && t.isActive);
  const others = tools.filter(t => t.category !== current.category && t.isActive);
  
  return [...sameCategory, ...others].slice(0, limit);
}

import { masterCategories } from './categories.ts';
export const categories = masterCategories;
